#include "piper_workbench/main_window.hpp"
#include "piper_workbench/backend_client.hpp"
using namespace Ui;
QWidget *MainWindow::makeCalibration(){
 auto *page=new QWidget;page->setObjectName("page");auto *layout=new QVBoxLayout(page);layout->setContentsMargins(20,20,20,16);layout->addWidget(text("标定与验证","pageTitle"));auto *bar=new QHBoxLayout;calibrationKind_=new QComboBox;calibrationKind_->addItems({"相机内参标定","手眼标定","TCP 固定点标定","手眼 TF 验证","TCP 定点姿态验证"});calibrationCamera_=new QComboBox;calibrationCamera_->addItems({"D455 固定相机","Dabai 腕载相机"});calibrationKind_->hide();bar->addWidget(calibrationKind_);auto *types=new QTabBar;types->addTab("内参标定");types->addTab("手眼标定");types->addTab("TCP 标定");types->addTab("手眼验证");types->addTab("TCP 验证");bar->addWidget(types);connect(types,&QTabBar::currentChanged,calibrationKind_,&QComboBox::setCurrentIndex);connect(calibrationKind_,qOverload<int>(&QComboBox::currentIndexChanged),types,&QTabBar::setCurrentIndex);bar->addWidget(calibrationCamera_);bar->addStretch();auto *start=button("启动采集 / 验证",true,"play");calibrationStartButton_=start;bar->addWidget(start);layout->addLayout(bar);connect(start,&QPushButton::clicked,this,[this,start]{startCalibration({},start);});
 auto *split=new QSplitter;layout->addWidget(split,1);auto *left=card("标定实时预览");auto *ll=static_cast<QVBoxLayout *>(left->layout());auto *view=new ImageView;view->waiting="等待原图 / 标定调试画面";images_["calibration:raw"]=view;ll->addWidget(view,1);ll->addWidget(text("原有标定板、采集判定和求解算法均复用现场版本。\n内参 / 手眼：计算后退出采集\nTCP：计算后可以继续补采"));split->addWidget(left);
 auto *middle=card("采样与操作");auto *ml=static_cast<QVBoxLayout *>(middle->layout());sampleTable_=new QTableWidget(0,4);sampleTable_->setHorizontalHeaderLabels({"采样","时间","角点","误差 px"});sampleTable_->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);sampleTable_->setEditTriggers(QAbstractItemView::NoEditTriggers);sampleTable_->setIconSize(QSize(48,36));sampleTable_->verticalHeader()->hide();ml->addWidget(sampleTable_,1);auto *buttons=new QGridLayout;int i=0;for(auto pair:QList<QPair<QString,QString>>{{"采集一组","capture"},{"撤回上一组","undo"},{"计算并保存","solve"},{"结束采集","finish"},{"停止验证","stop"}}){auto *b=button(pair.first,pair.second=="capture"||pair.second=="solve",pair.second=="capture"?"capture":"save");calibrationButtons_[pair.second]=b;buttons->addWidget(b,i/2,i%2);++i;connect(b,&QPushButton::clicked,this,[this,pair,b]{sendCalibration(pair.second,b);});}ml->addLayout(buttons);calibrationState_=text("尚未启动采集","notice");ml->addWidget(calibrationState_);split->addWidget(middle);
 auto *right=card("结果与验证设置");auto *rl=static_cast<QVBoxLayout *>(right->layout());auto *verification=new QWidget;auto *vl=new QVBoxLayout(verification);vl->setContentsMargins(0,0,0,0);auto *form=new QFormLayout;verifyAngle_=new QDoubleSpinBox;verifyAngle_->setRange(.1,30);verifyAngle_->setValue(5);verifyAngle_->setSuffix(" °");verifySteps_=new QSpinBox;verifySteps_->setRange(1,100);verifySteps_->setValue(5);verifySpeed_=new QDoubleSpinBox;verifySpeed_->setRange(.005,.1);verifySpeed_->setDecimals(3);verifySpeed_->setValue(.03);form->addRow("TCP 摆动角度",verifyAngle_);form->addRow("每边步数",verifySteps_);form->addRow("TCP 速度比例",verifySpeed_);vl->addLayout(form);auto *axes=new QHBoxLayout;axes->addWidget(text("摆动轴"));for(QString axis:{"X","Y","Z"}){auto *check=new QCheckBox(axis);check->setChecked(axis!="Z");verifyAxes_<<check;axes->addWidget(check);}axes->addStretch();vl->addLayout(axes);auto *verifyButtons=new QHBoxLayout;for(auto pair:QList<QPair<QString,QString>>{{"规划验证","plan"},{"执行验证","execute"}}){auto *b=button(pair.first,pair.second=="execute","play");calibrationLaunchButtons_<<b;verifyButtons->addWidget(b);connect(b,&QPushButton::clicked,this,[this,pair,b]{calibrationKind_->setCurrentIndex(4);startCalibration(pair.second,b);});}vl->addLayout(verifyButtons);vl->addWidget(text("执行前请将机械臂放到可活动、无遮挡的位置。默认 X、Y 轴，复用现场 sweep 轨迹。","notice"));rl->addWidget(verification);verification->hide();connect(calibrationKind_,qOverload<int>(&QComboBox::currentIndexChanged),verification,[verification](int i){verification->setVisible(i==4);});resultSummary_=text("尚无求解结果\n采集后显示真实样本数、误差与文件来源","notice");rl->addWidget(resultSummary_);resultText_=new QPlainTextEdit;resultText_->setReadOnly(true);resultText_->setPlaceholderText("求解结果、原始误差、文件路径将显示于此");rl->addWidget(resultText_,1);auto *select=button("在参数页选用结果",true,"save");rl->addWidget(select);connect(select,&QPushButton::clicked,this,[this]{showPage(1);debugTabs_->setCurrentIndex(3);refreshFiles();});split->addWidget(right);split->setSizes({430,380,450});
 auto *logs=card("工具输出 · 原文保留");auto *loglayout=static_cast<QVBoxLayout *>(logs->layout());calibrationLog_=new QPlainTextEdit;calibrationLog_->setReadOnly(true);calibrationLog_->setMaximumBlockCount(10000);calibrationLog_->setMaximumHeight(130);loglayout->addWidget(calibrationLog_);Ui::collapsible(logs);layout->addWidget(logs);updateCalibrationButtons();return page;
}
void MainWindow::startCalibration(QString mode,QPushButton *button){QStringList kinds={"intrinsics","handeye","tcp","verify-handeye","verify-tcp"};QJsonArray axes;for(auto *check:verifyAxes_)if(check->isChecked())axes.append(check->text().toLower());if(calibrationKind_->currentIndex()==4&&axes.isEmpty()){showError("请选择至少一个摆动轴");return;}QJsonObject options{{"mode",mode.isEmpty()?"plan":mode},{"angle_deg",verifyAngle_->value()},{"steps",verifySteps_->value()},{"speed",verifySpeed_->value()},{"axes",axes}};request(button?button:calibrationStartButton_,"calibration.start",{{"kind",kinds[calibrationKind_->currentIndex()]},{"camera_id",calibrationCamera_->currentIndex()==0?"d455":"dabai"},{"options",options}},[this](QJsonValue v){calibrationSession_=v.toObject()["session_id"].toString();calibrationRunning_=true;updateCalibrationButtons();calibrationState_->setText("采集程序已启动 · "+v.toObject()["directory"].toString());},"正在启动…",{},true);}
void MainWindow::sendCalibration(QString action,QPushButton *button){request(button,"calibration.input",{{"session_id",calibrationSession_},{"action",action}},[this](QJsonValue){refresh();},"提交中…","已提交");}
